const PATTERN = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;
const UNIT_SECONDS = [3600, 60, 1];

export function parseDuration(text) {
  if (typeof text !== 'string') {
    throw new TypeError(`duration must be a string, got ${typeof text}`);
  }

  const match = PATTERN.exec(text.trim());
  const groups = match ? match.slice(1) : [];
  if (groups.every((group) => group === undefined)) {
    throw new TypeError(`invalid duration: ${JSON.stringify(text)}`);
  }

  return groups.reduce(
    (total, digits, i) => total + (digits === undefined ? 0 : Number(digits) * UNIT_SECONDS[i]),
    0,
  );
}

