import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseDuration } from './duration.mjs';

test('is exported', () => {
  assert.equal(typeof parseDuration, 'function');
});

test('parses single units', () => {
  assert.equal(parseDuration('2h'), 7200);
  assert.equal(parseDuration('5m'), 300);
  assert.equal(parseDuration('90s'), 90);
});

test('parses combined units', () => {
  assert.equal(parseDuration('1h30m'), 5400);
  assert.equal(parseDuration('1m30s'), 90);
  assert.equal(parseDuration('1h30m15s'), 5415);
});

test('allows zero values', () => {
  assert.equal(parseDuration('0s'), 0);
  assert.equal(parseDuration('1h0m5s'), 3605);
  assert.equal(parseDuration('0h0m0s'), 0);
});

test('ignores surrounding whitespace', () => {
  assert.equal(parseDuration('  1h30m \t'), 5400);
});

test('rejects empty and whitespace-only input', () => {
  assert.throws(() => parseDuration(''), TypeError);
  assert.throws(() => parseDuration('   '), TypeError);
});

test('rejects non-string input', () => {
  assert.throws(() => parseDuration(90), TypeError);
  assert.throws(() => parseDuration(null), TypeError);
});

test('rejects unknown units', () => {
  assert.throws(() => parseDuration('5d'), TypeError);
  assert.throws(() => parseDuration('1h2x'), TypeError);
});

test('rejects decimals', () => {
  assert.throws(() => parseDuration('1.5h'), TypeError);
  assert.throws(() => parseDuration('1h0.5m'), TypeError);
});

test('rejects negative numbers', () => {
  assert.throws(() => parseDuration('-5s'), TypeError);
  assert.throws(() => parseDuration('1h-5m'), TypeError);
});

test('rejects repeated units', () => {
  assert.throws(() => parseDuration('1h2h'), TypeError);
  assert.throws(() => parseDuration('1m2m3s4m'), TypeError);
});

test('rejects units out of order', () => {
  assert.throws(() => parseDuration('30m1h'), TypeError);
  assert.throws(() => parseDuration('5s1m'), TypeError);
});

test('rejects a number without a unit', () => {
  assert.throws(() => parseDuration('90'), TypeError);
  assert.throws(() => parseDuration('1h30'), TypeError);
});

test('rejects a unit without a number', () => {
  assert.throws(() => parseDuration('h'), TypeError);
  assert.throws(() => parseDuration('1hm'), TypeError);
});

test('rejects whitespace inside the value', () => {
  assert.throws(() => parseDuration('1h 30m'), TypeError);
});

